from types import MappingProxyType


def migrate_event(row: dict) -> dict:
    """Convert one legacy AUD_EVENT row to its modern event representation."""
    timestamp = row["EVT_TS"]
    return {
        "evt_id": int(row["EVT_ID"]),
        "ts": (
            f"{timestamp[:4]}-{timestamp[4:6]}-{timestamp[6:8]}"
            f"T{timestamp[8:10]}:{timestamp[10:12]}:{timestamp[12:14]}"
        ),
        "code": row["EVT_CD"],
        "user_id": row["USR_ID"],
        "entity": row["ENT_NAME"],
        "entity_id": row["ENT_ID"],
        "old_val": row["OLD_VAL"],
        "new_val": row["NEW_VAL"],
    }


class AuditStore:
    """An append-only in-memory audit event store."""

    __slots__ = ("_records",)

    def __init__(self) -> None:
        object.__setattr__(self, "_records", ())

    def __setattr__(self, name: str, value: object) -> None:
        raise AttributeError("AuditStore is append-only")

    def append(self, event: dict) -> None:
        record = MappingProxyType(dict(event))
        object.__setattr__(self, "_records", self._records + (record,))

    def events(self) -> list[dict]:
        return [dict(record) for record in self._records]

    def __len__(self) -> int:
        return len(self._records)


def migrate(rows: list[dict], store: AuditStore | None = None) -> AuditStore:
    if store is None:
        store = AuditStore()

    existing_ids = {event["evt_id"] for event in store.events()}

    for row in sorted(rows, key=lambda item: int(item["EVT_ID"])):
        event = migrate_event(row)
        if event["evt_id"] not in existing_ids:
            store.append(event)
            existing_ids.add(event["evt_id"])

    return store
